INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (1809, 'Trường Cao Đẳng Sư Phạm Đà Lạt', 'truong-cao-dang-su-pham-da-lat', '<p>Trường Cao Đẳng Sư Phạm Đà Lạt là một điểm tham quan thú vị dành cho những du khách muốn khám phá Đà Lạt. Đây là một ngôi trường cổ được xây dựng từ <strong>năm 1927</strong> bởi một <strong>kiến trúc sư người Pháp</strong> tên là <strong>Moncent</strong>. Đặc biệt nơi đây còn được bình chọn là <strong>một trong 1000 công trình kiến trúc độc đáo của thế kỷ 20</strong>.</p>
<p><figure id="attachment_1804" aria-describedby="caption-attachment-1804" style="width: 600px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-1804" src="https://media.huynhhieutravel.com/Trường-cao-đẳng-sư-phạm-Đà-Lạt.jpg" alt="Trường Cao Đẳng Sư Phạm Đà Lạt" width="600" height="395"><figcaption id="caption-attachment-1804" class="wp-caption-text">Trường Cao Đẳng Sư Phạm Đà Lạt</figcaption></figure></p>
<h2>Thông tin trường cao đẳng sư phạm Đà Lạt</h2>
<p>Trường cao đẳng sư phạm Đà Lạt nằm cách trung tâm thành phố Đà Lạt hơn <strong>2km</strong>. Đường đi khá <strong>gần và dễ đi</strong>. Đây là một địa điểm du lịch thú vị với một kiến trúc độc đáo. Ngôi trường với lối kiến trúc cổ kính, thoáng đã tạo nên một điểm nhấn cho những bức hình tuyệt vời của khách du lịch.</p>
<p><strong>Địa chỉ</strong>:&nbsp;29 Yersin, Phường 10, Thành phố Đà Lạt, Lâm Đồng</p>
<p><strong>Số điện thoại</strong>:&nbsp;02633822489</p>
<p><strong>Website</strong>:&nbsp;http://cdspdalat.edu.vn/</p>
<p><iframe style="border: 0;" src="https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d15613.686510309757!2d108.4516561!3d11.9452833!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0x610fd1318bbad584!2zVHLGsOG7nW5nIENhbyDEkeG6s25nIHPGsCBwaOG6oW0gxJDDoCBM4bqhdA!5e0!3m2!1svi!2s!4v1536417662508" width="600" height="450" frameborder="0" allowfullscreen="allowfullscreen"></iframe></p>
<h3>Lịch sử và nguồn gốc trường cao đẳng sư phạm Đà Lạt</h3>
<p>Trường cao đẳng sư phạm Đà Lạt được thành lập vào <strong>năm 1927</strong> do kiến trúc sư người Pháp là&nbsp;Moncet thiết kế. Bạn đầu trường được xây dựng cho con em người Pháp và những phú hộ giàu có người Việt học tập. Cái tên ban đầu được đặt là&nbsp;Petit Lycée Dalat sau đó được đổi tên thành&nbsp;Grand Lycée de Dalat. Tiếp sau đó lại đổi thành Lycée Yersin để tưởng niệm bác sĩ Alexandre Yersin. Sau này đổi tên lại thành trường cao đẳng sư phạm Đà Lạt. Nơi đây còn được công nhận là di tích kiến trúc quốc gia.</p>
<h3>Kiến trúc trường cao đẳng sư phạm Đà Lạt</h3>
<p>Nguyên vật liệu đầu tiên xây dựng trường đều được mang từ Pháp sang như gạch ép để xây dựng tường và ngói&nbsp;ardoise màu xanh để lợp mái.</p>
<p>Sau này dù qua hơn 90 năm nhưng tổng thể kiến trúc của trường vẫn không thay đổi nhiều. Tuy có một số thứ đã được thay mới như mái ngói, một số bức tường nhưng vẫn cố gắng giữ toàn vẹn kiến trúc cũ.</p>
<p>Tuy nhiên tháp chuông của dãy nhà hình cung lại bị hư hỏng nặng và chiếc đồng hồ trong đó đã bị mất và không có đồ vật thay thế. Hiện giờ chúng ta chỉ có thể thấy nền gạch bị lún vào bởi vết tích chiếc đồng hồ cũ.</p>
<h4>Khu giảng đường chính vòng cung trường cao đẳng sư phạm Đà Lạt</h4>
<p>Chiều dài phía trước của giảng đường khoảng 77m, phía sau khoảng 90m bao gồm 3 lầu và 24 phòng học. Ý tưởng kiến trúc ban đầu của vòng cung là như một cuốn sách mở ra với biểu tưởng khát vọng tri thức.</p>
<h4>Tháp chuông trường cao đẳng sư phạm Đà Lạt</h4>
<p>Cuối dãy nhà giảng đường chính là một tháp chuông nằm ở vị trí cao nhất. Tháp chuông là một biểu tượng văn hóa của Pháp về sự vươn lên của tri thức, nâng tầm ước mơ.</p>
<h4>Khoảng sân rộng giữa trường</h4>
<p>Nơi đây là một khoảng sân trống để phục vụ các môn thể chất, thể dục của trường. Ngoài ra còn trồng những hàng cây tùng rất đẹp như châu Âu.</p>
<h4>Các dãy nhà khác</h4>
<p>Ngoài giảng đường chính đặc trưng trường có nhiều dãy nhà cao 2-3 tầng khác phục vụ cho công việc giảng dạy và học tập: phòng học, phòng thí nghiệm, ký túc xá, phòng giám hiệu, phòng họp,&#8230;</p>
<p><figure id="attachment_1808" aria-describedby="caption-attachment-1808" style="width: 475px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-1808" src="https://media.huynhhieutravel.com/Trường-cao-đẳng-sư-phạm-Đà-Lạt5.jpg" alt="Bức tường tạo nên một background chụp hình tuyệt vời" width="475" height="594"><figcaption id="caption-attachment-1808" class="wp-caption-text">Bức tường tạo nên một background chụp hình tuyệt vời</figcaption></figure></p>
<h2>Đường đi đến Trường cao đẳng sư phạm Đà Lạt</h2>
<p>Đường đi đến trường cao đẳng sư phạm Đà Lạt khá dễ đi và gần. Nó nằm cách trung tâm Đà Lạt khoảng hơn 2km. Bạn có thể đi xe hơi hoặc xe máy đều được. Đường ở đây đủ cho xe 45 chỗ đi vào bạn nhé!</p>
<p>Bạn có thể điền tọa độ của bạn vào link này để tìm đường đi: <a href="https://www.google.com/maps/dir//Tr%C6%B0%E1%BB%9Dng+Cao+%C4%91%E1%BA%B3ng+S%C6%B0+ph%E1%BA%A1m+%C4%90%C3%A0+L%E1%BA%A1t,+Yersin,+Ph%C6%B0%E1%BB%9Dng+10,+Th%C3%A0nh+ph%E1%BB%91+%C4%90%C3%A0+L%E1%BA%A1t,+L%C3%A2m+%C4%90%E1%BB%93ng/@10.9790544,105.9949444,8z/data=!4m8!4m7!1m0!1m5!1m1!1s0x3171131fbc36e679:0x610fd1318bbad584!2m2!1d108.4516561!2d11.9452833">Tọa độ và cách đi đến trường cao đẳng sư phạm Đà Lạt</a></p>
<h2>Kinh nghiệm đi Trường cao đẳng sư phạm Đà Lạt</h2>
<ul>
<li>Bạn nhớ đem chứng minh nhân dân theo vì họ sẽ giữ chúng khi vào cổng.</li>
<li>Bạn phải đi sau 16h vì hiện đã có quy định giờ tham quan.</li>
<li>Với kiến trúc cổ kính và tòa nhà xưa, bạn nên chọn phụ kiện thời trang phù hợp để chụp những bức ảnh đẹp ở đây.</li>
<li>Bạn nên chụp hình cưới ở đây. Hình lên sẽ cực kỳ xinh đẹp đấy bạn nhé!</li>
</ul>
<p><figure id="attachment_1805" aria-describedby="caption-attachment-1805" style="width: 475px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-1805" src="https://media.huynhhieutravel.com/Trường-cao-đẳng-sư-phạm-Đà-Lạt2.jpg" alt="Khách du lịch chụp hình trong khuôn viên trường" width="475" height="600"><figcaption id="caption-attachment-1805" class="wp-caption-text">Khách du lịch chụp hình trong khuôn viên trường</figcaption></figure></p>
<h3>Thời điểm thich hợp đi Trường cao đẳng sư phạm Đà Lạt</h3>
<p>Trường cao đẳng sư phạm Đà Lạt gần như mở quanh năm, nhưng bạn cũng nên lựa chọn thời điểm thích hợp để đi. Bạn hãy tránh dịp lễ tết ra vì sẽ khá đông du khách đến đây và nó sẽ rất mệt mỏi khi chen lấn giữa dòng người đông đúc.</p>
<p>Ngoài ra vì hiện tại khách tham quan khá đông ảnh hưởng đến sinh viên nên nhà trường đã quy định lại giờ giấc tham quan:</p>
<ul>
<li>Từ thứ 2 đến thứ 7: Từ 11h30 đến 13h00 và sau 16h00.</li>
<li>Ngày chủ nhật: Mở cửa tự do trong giờ hành chính.</li>
</ul>
<h2>Giá vé tham quan Trường cao đẳng sư phạm Đà Lạt</h2>
<p>Giá vé vào cổng là hoàn toàn miễn phí nhưng bạn phải gửi Chứng Minh Nhân Dân lại khi vào cổng.</p>
<p><figure id="attachment_1807" aria-describedby="caption-attachment-1807" style="width: 597px" class="wp-caption aligncenter"><img loading="lazy" decoding="async" class="size-full wp-image-1807" src="https://media.huynhhieutravel.com/Trường-cao-đẳng-sư-phạm-Đà-Lạt4.jpg" alt="Một góc của trường cao đẳng sư phạm Đà Lạt" width="597" height="597" srcset="https://media.huynhhieutravel.com/Trường-cao-đẳng-sư-phạm-Đà-Lạt4.jpg 597w, https://media.huynhhieutravel.com/Trường-cao-đẳng-sư-phạm-Đà-Lạt4-150x150.jpg 150w" sizes="(max-width: 597px) 100vw, 597px" /><figcaption id="caption-attachment-1807" class="wp-caption-text">Một góc của trường cao đẳng sư phạm Đà Lạt</figcaption></figure></p>
<h2>Review&nbsp;Trường cao đẳng sư phạm Đà Lạt</h2>
<p>Trường cao đẳng sư phạm Đà Lạt là ngôi trường có kiến trúc cổ xưa nhất Đà Lạt hiện nay. Nó được&nbsp;Hội Kiến trúc sư thế giới bình chọn 1 trong 1000 kiến trúc nổi bật của thế kỷ 20. Kiến trúc của ngôi trường nổi bật với hình vòng cung, tường gạch trần đỏ mang phong cách cổ điển rất xinh đẹp. Đặc biệt, ngôi trường lên hình rất ảo dịu. Nơi đây rất thích hợp các bạn trẻ đến chụp hình và check in. Đánh giá 8/10.</p>
<h3>Đánh giá của khách du lịch về Trường cao đẳng sư phạm Đà Lạt</h3>
<ul>
<li>Bạn Tuấn Foi đánh giá 5/5: &#8220;Đà Lạt mộng mơ, khung cảnh thanh bình. Thích hợp cho các bạn trẻ đến để tham quan chụp hình lưu niệm, kể cả việc đi chụp hình cưới tại đây. Đúng là nơi lý tưởng của gió trời Đà Lạt se lạnh. Nếu bạn chưa đến hay còn chần chờ gì nữa hãy nhanh tay chuẩn bị sắp xếp thời gian để trải nghiệm khung cảnh tuyệt đẹp. Thật tuyệt vời&#8221;.</li>
</ul>
<p>Cảm ơn review rất có tâm của bạn Tuấn Foi, một review cực kỳ tươi sáng và có tâm!</p>
<ul>
<li>Bạn Nguyên Phú đánh giá 4/5: &#8220;Trường cao đẳng sư phạm Đà Lạt vẫn đang hoạt động và mở cửa cho du khách đến tham quan. Một trong những địa điểm mang giá trị lịch sử và kiến trúc của Đà Lạt.</li>
</ul>
<p>Cảm ơn bạn đã giới thiệu trường cao đẳng sư phạm Đà Lạt với mọi người!</p>
<p><figure id="attachment_1810" aria-describedby="caption-attachment-1810" style="width: 363px" class="wp-caption alignnone"><img loading="lazy" decoding="async" class="size-full wp-image-1810" src="https://media.huynhhieutravel.com/Review-trường-cao-đẳng-sư-phạm-Đà-Lạt.png" alt="Review trường cao đẳng sư phạm Đà Lạt" width="363" height="501"><figcaption id="caption-attachment-1810" class="wp-caption-text">Review trường cao đẳng sư phạm Đà Lạt</figcaption></figure></p>
<p><em><strong>Clip về trường CĐSP Đà Lạt từ kênh YT Zai Tri</strong></em></p>
<p><iframe title="Trường cao đẳng sư phạm Đà Lạt - CDSP DaLat lối kiến trúc Pháp thu hút du khách tham quan chụp ảnh" width="800" height="450" src="https://www.youtube.com/embed/g4xGAGnyun0?feature=oembed" frameborder="0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></p>
<p>Bài viết gần như tổng hợp tất cả những hiểu biết của mình về Trường cao đẳng sư phạm Đà Lạt. Nếu có thêm thông tin gì khác hãy cùng chia sẽ bạn nhé!</p>
<p>Email:&nbsp;<em><strong>huynhtronghieu1911@gmail.com</strong></em></p>
